291	            NotificationDeliveryPolicy.shouldDeliverOnBatchTick(it.priority, settings, time)
292	        }.toMutableList()
293	        val outcomes = mutableListOf<DeliveryOutcome>()
294	        while (pending.isNotEmpty() && outcomes.size < MAX_BATCH_ATTEMPTS) {
295	            val candidate = NotificationDeliveryPolicy.orderCandidates(pending, environment.queuePreferences()).first()
296	            pending.removeAll { it.id == candidate.id }
297	            val current = rows.find(candidate.id)
298	            val outcome = if (current == null || current.isCleared || explicitlyRemoved(candidate.id)) {
299	                rows.markCleared(candidate.id)
300	                DeliveryOutcome.Cleared(candidate.id)
