307	            if (outcome is DeliveryOutcome.CommitPending) break
308	            if (outcome is DeliveryOutcome.Delivered) {
309	                rows.nextHead(candidate)?.let { next -> if (pending.none { it.id == next.id }) pending += next }
310	            }
311	        }
