315	    private suspend fun deliver(item: NotificationItem, reserved: List<NotificationItem> = emptyList()): DeliveryOutcome {
316	        // Recheck callback-side tombstones at the effect boundary, even if removal work is queued.
317	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
318	            rows.markCleared(item.id)
319	            return DeliveryOutcome.Cleared(item.id)
320	        }
321	        if (item.deliveryInvalidated || ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
322	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
323	        val time = environment.timeContext()
324	        val schedule = environment.schedule()
325	        val setting = environment.settings()[item.priority] ?: PriorityDeliverySetting.defaultFor(item.priority)
326	        val decision = NotificationDeliveryPolicy.canDeliverNow(item.priority, setting, schedule, time, budget.read())
327	        if (setting.budgetBehavior == BudgetBehavior.RESPECTING && reserved.isNotEmpty()) {
328	            val points = reserved.sumOf { it.snoozePriority?.pointCost ?: 0 }
329	            val limit = NotificationDeliveryPolicy.findActivePeriod(schedule, time.scheduleMinuteOfDay)?.budgetPoints ?: 0
330	            if (decision.updatedBudget.spentPoints.toLong() + points + item.priority.pointCost > limit) return DeliveryOutcome.Deferred(item.id)
331	        }
332	        if (!decision.canDeliver) return DeliveryOutcome.Deferred(item.id)
333	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
334	            rows.markCleared(item.id)
335	            return DeliveryOutcome.Cleared(item.id)
336	        }
337	        if (ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
338	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
339	        return when (val post = postSafely(item)) {
340	            is PostResult.Failed -> DeliveryOutcome.PostFailed(item.id, post.reason)
341	            PostResult.Posted -> {
342	                val charged = NotificationDeliveryPolicy.recordPassthrough(item.priority, setting, schedule, time.scheduleMinuteOfDay, decision.updatedBudget)
343	                val entry = if (setting.budgetBehavior == ly.com.tahaben.notification_filter_domain.model.BudgetBehavior.RESPECTING && item.priority.pointCost > 0)
344	                    BudgetSpendEntry(item.appName.orEmpty(), item.title.orEmpty(), item.priority, item.priority.pointCost,
345	                        System.currentTimeMillis(), charged.periodStartMinute, charged.accountingId, java.util.UUID.randomUUID().toString()) else null
346	                // At most one unresolved effect is retained. All subsequent mutations recover it under this gate.
347	                completion = Completion(item.id, charged, entry)
348	                try { finishCompletion() }
349	                catch (cancelled: kotlinx.coroutines.CancellationException) { throw cancelled }
350	                catch (_: Exception) { return DeliveryOutcome.CommitPending(item.id) }
